# Verify against batch_020.json
with open(r'C:\Users\nipon\Documents\opencode\idiom-master\scratch\ox_mnemonics\batch_020.json', 'r', encoding='utf-8') as f:
    source = json.load(f)

source_lemmas = [item['lemma'] for item in source]
assert len(source_lemmas) == len(data) == 50, f"Length mismatch: {len(source_lemmas)} vs {len(data)}"
for lemma in source_lemmas:
    assert lemma in data, f"Missing lemma: {lemma}"
    assert f"({lemma})" in data[lemma], f"Missing ({lemma}) in mnemonic: {data[lemma]}"

output_path = r'C:\Users\nipon\Documents\opencode\idiom-master\scratch\ox_mnemonics_done\batch_020_done.json'
with open(output_path, 'w', encoding='utf-8') as f:
    json.dump(data, f, ensure_ascii=False, indent=2)

print(f"Successfully validated and wrote {len(data)} mnemonics to {output_path}")
